// Optional filters use a prepared source code and/or a manager UUID.
const source = null;
const manager_id = null;
const query = {start_date: '2026-06-01', end_date: '2026-08-31', cutoff_date: '2026-10-31'};
if ($('Daily 09:00').isExecuted) {
  const trigger = DateTime.fromISO($input.first().json.timestamp, {setZone: true});
  if (!trigger.isValid) throw new Error('Invalid schedule timestamp');
  const day = trigger.setZone('Europe/Moscow').minus({days: 1}).toISODate();
  Object.assign(query, {start_date: day, end_date: day, cutoff_date: day});
}
if (source !== null) query.source = source;
if (manager_id !== null) query.manager_id = manager_id;
return [{json: query}];

const response = $input.first().json;
const status = response.statusCode;
const attempt = $runIndex + 1;
const transportFailure = status === undefined && Boolean(response.error);
const temporary = transportFailure || [408, 429, 500, 502, 503, 504].includes(status);
if (temporary && attempt < 3) return [{json: {retry: true}}];
if (transportFailure) throw new Error('Metrics API unavailable or timed out (3 attempts)');
if (status !== 200) throw new Error('Metrics API HTTP ' + (Number.isInteger(status) ? status : 'unknown'));

let report;
try {
  report = JSON.parse(response.body);
} catch {
  throw new Error('Metrics API returned invalid JSON');
}
const query = $('Report period').first().json;
if (!report || !['start_date', 'end_date', 'cutoff_date'].every(k => report.period?.[k] === query[k])) {
  throw new Error('Metrics API returned an unexpected report period');
}
function decimal(value) {
  return typeof value === 'string' && /^\d+(?:\.\d{1,2})?$/.test(value);
}
function kpis(row) {
  if (!row || !decimal(row.paid_amount_rub) || !Number.isSafeInteger(row.paying_leads) || row.paying_leads < 0
      || !(row.average_paid_check_rub === null || decimal(row.average_paid_check_rub))
      || !(row.lesson_to_payment_pct === null || (decimal(row.lesson_to_payment_pct) && Number(row.lesson_to_payment_pct) <= 100))) {
    throw new Error('Metrics API returned missing or invalid KPI fields');
  }
  return {paid_amount_rub: row.paid_amount_rub, paying_leads: row.paying_leads,
    average_paid_check_rub: row.average_paid_check_rub, lesson_to_payment_pct: row.lesson_to_payment_pct};
}
function breakdown(rows, key) {
  if (rows === undefined) return [];
  if (!Array.isArray(rows)) throw new Error('Invalid breakdown');
  return rows.map(row => {
    if (typeof row?.[key] !== 'string' || !row[key].trim()) throw new Error('Missing breakdown label');
    return {[key]: row[key], ...kpis(row)};
  });
}
const result = {report_id: JSON.stringify([query.start_date, query.end_date, query.cutoff_date, query.source ?? null, query.manager_id ?? null]),
  period: report.period, filters: {source: query.source ?? null, manager_id: query.manager_id ?? null}, total: kpis(report.total)};
for (const [field, key] of [['by_source', 'source'], ['by_manager', 'manager_id']]) {
  const rows = breakdown(report[field], key);
  if (rows.length) result[field] = rows;
}
return [{json: {retry: false, report: result}}];

const report = $input.first().json.report;
function display(value, unit) {
  if (value === null) return 'нет данных';
  const [whole, fraction = ''] = value.split('.');
  return whole.replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + ',' + fraction.padEnd(2, '0') + ' ' + unit;
}
const {start_date, end_date, cutoff_date} = report.period;
const t = report.total;
const lines = [
  'Продажи за ' + start_date + ' — ' + end_date + ' (срез ' + cutoff_date + ')',
  'Сумма успешных оплат — ' + display(t.paid_amount_rub, '₽'),
  'Оплатившие лиды — ' + t.paying_leads,
  'Средний оплаченный чек — ' + display(t.average_paid_check_rub, '₽'),
  'Конверсия из урока в оплату — ' + display(t.lesson_to_payment_pct, '%')
];
return [{json: {...report, text: lines.join('\n')}}];

// Enable these independently after binding EduFlow Telegram and checking the private recipient.
const sendManual = false;
const sendScheduled = false;
const scheduled = $('Daily 09:00').isExecuted;
const report = $input.first().json;
const t = report.total;
const decimal = v => typeof v === 'string' && /^\d+(?:\.\d{1,2})?$/.test(v);
if (!t || !decimal(t.paid_amount_rub) || !Number.isSafeInteger(t.paying_leads) || t.paying_leads < 0 ||
    !(t.average_paid_check_rub === null || decimal(t.average_paid_check_rub)) ||
    !(t.lesson_to_payment_pct === null || decimal(t.lesson_to_payment_pct))) {
  throw new Error('Telegram report contains invalid KPIs');
}
const text = ['📊 EduFlow AI | Отчёт по продажам', report.text, '✅ Отчёт сформирован автоматически'].join('\n\n');
if (!report.text || text.length > 4096 || /\b(?:null|NaN|Infinity|undefined)\b/.test(text)) {
  throw new Error('Telegram report text is invalid');
}
return [{json: {enabled: scheduled ? sendScheduled : sendManual, period: report.period,
  report_id: report.report_id, execution_id: String($execution.id), started_at: $now.toISO(), text}}];

const request = $('Prepare Telegram delivery').first().json;
const input = $input.first().json;
const delivery = input.delivery;
const record = {started_at: request.started_at, execution_id: request.execution_id, period: request.period,
  status: 'skipped', attempts: 0, attempt_log: [], message_id: null, error_code: null};
if (!request.enabled) return [{json: record}];
if (!delivery || delivery.execution_id !== request.execution_id ||
    !['sent', 'already_sent', 'failed', 'unknown'].includes(delivery.status) ||
    !Number.isInteger(delivery.attempts) || !Array.isArray(delivery.attempt_log) ||
    delivery.attempts !== delivery.attempt_log.length ||
    (['sent', 'already_sent'].includes(delivery.status) && !(Number.isSafeInteger(delivery.message_id) && delivery.message_id > 0))) {
  return [{json: {...record, status: 'unknown', attempts: null, error_code: 'delivery_confirmation_missing'}}];
}
return [{json: {...record, status: delivery.status, attempts: delivery.attempts,
  attempt_log: delivery.attempt_log, message_id: delivery.message_id, error_code: delivery.error_code}}];
